1	'use strict';
2	
3	// Factory + facade for @matter-server/ws-client.
4	//
5	// The upstream MatterClient is ESM-only and fires only generic "nodes_changed"
6	// events — no per-attribute deltas. We need the per-attribute info to emit
7	// topic-shaped Node-RED msgs.
8	//
9	// Solution: intercept the WebSocket's 'message' listener at registration time
10	// (via a wrapped WS factory). Each incoming message gets parsed and re-emitted
11	// as a typed event on our own EventEmitter BEFORE being passed to MatterClient's
12	// internal handler, so MatterClient's state cache stays intact and we get
13	// per-attribute deltas as a side channel.
14	
15	const { EventEmitter } = require('events');
16	
17	// @matter-server/ws-client (through at least 1.1.0) logs every incoming WS frame, every outgoing
18	// command and every event via console.debug with no off switch, which floods the Node-RED log
19	// (especially metered devices). By default we drop those per-frame/event/command debug lines
20	// ("WebSocket …" and "Incoming event"); the low-frequency lifecycle logs (Connected/Closed/Trying
21	// to connect) and all other console.debug output are preserved. Set MATTERJS_WS_DEBUG=1 to opt out
22	// and let everything through (debugging). Installed once per process.
23	(function silenceMatterWsDebug() {
24	    if (process.env.MATTERJS_WS_DEBUG === '1') { return; }
25	    if (console.__hal2MatterWsDebugFiltered) { return; }
26	    const orig = (console.debug || console.log).bind(console);
27	    console.debug = function (first) {
28	        if (typeof first === 'string' && (first.startsWith('WebSocket ') || first === 'Incoming event')) { return; }
29	        return orig.apply(null, arguments);
30	    };
31	    console.__hal2MatterWsDebugFiltered = true;
32	})();
33	
34	let _matterClientModule = null;
35	
36	async function loadMatterClientModule() {
37	    if (_matterClientModule === null) {
38	        _matterClientModule = await import('@matter-server/ws-client');
39	    }
40	    return _matterClientModule;
41	}
42	
43	let _wsCtor = null;
44	async function loadWebSocketCtor() {
45	    if (_wsCtor) return _wsCtor;
46	    if (typeof globalThis.WebSocket === 'function') {
47	        _wsCtor = globalThis.WebSocket;
48	        return _wsCtor;
49	    }
50	    const wsMod = await import('ws');
51	    _wsCtor = wsMod.WebSocket || wsMod.default;
52	    return _wsCtor;
53	}
54	
55	function tapWebSocket(rawWs, emitter) {
56	    const origAdd = rawWs.addEventListener.bind(rawWs);
57	    rawWs.addEventListener = function (type, listener, options) {
58	        if (type !== 'message') return origAdd(type, listener, options);
59	        const wrapped = (event) => {
60	            try {
61	                const raw = (typeof event.data === 'string')
62	                    ? event.data
63	                    : (event.data && typeof event.data.toString === 'function' ? event.data.toString() : null);
64	                if (raw) {
65	                    let parsed;
66	                    try {
67	                        parsed = JSON.parse(raw);
68	                    } catch (parseErr) {
69	                        // Surface as 'error' but only when the payload looks like it was meant
70	                        // to be an event (starts with `{`). Suppress for empty/control frames.
71	                        if (raw.trim().startsWith('{')) {
72	                            emitter.emit('error', Object.assign(new Error('ws parse: ' + parseErr.message), {
73	                                source: 'ws_parse',
74	                                preview: String(raw).slice(0, 200),
75	                            }));
76	                        }
77	                        return listener(event);
78	                    }
79	                    try {
80	                        dispatchTapped(parsed, emitter);
81	                    } catch (dispatchErr) {
82	                        emitter.emit('error', Object.assign(dispatchErr, { source: 'dispatch' }));
83	                    }
84	                }
85	            } catch (_) { /* unreachable */ }
86	            return listener(event);
87	        };
88	        return origAdd(type, wrapped, options);
89	    };
90	    return rawWs;
91	}
92	
93	function dispatchTapped(parsed, emitter) {
94	    if (!parsed || typeof parsed !== 'object') return;
95	    if (!parsed.event) return; // command response, not an event
96	
97	    switch (parsed.event) {
98	        case 'attribute_updated': {
99	            const data = parsed.data;
100	            if (!Array.isArray(data) || data.length < 3) return;
101	            const [nodeId, path, value] = data;
102	            const parts = String(path).split('/');
103	            if (parts.length < 3) return;
104	            const [endpoint, cluster, attribute] = parts;
105	            emitter.emit('attribute_changed', {
106	                nodeId,
107	                endpoint: Number(endpoint),
108	                cluster: Number(cluster),
109	                attribute: Number(attribute),
110	                value,
111	            });
112	            return;
113	        }
114	        case 'node_event': {
115	            const d = parsed.data;
116	            if (!d || typeof d !== 'object') return;
117	            emitter.emit('node_event', d);
118	            return;
119	        }
120	        case 'node_added':
121	        case 'node_removed':
122	        case 'node_updated':
123	            if (parsed.data) emitter.emit(parsed.event, parsed.data);
124	            return;
125	        default:
126	            emitter.emit('raw_event', parsed);
127	            return;
128	    }
129	}
130	
131	/**
132	 * Build a MatterBridge facade — wraps the official MatterClient and exposes:
133	 *   .start()                 — connect + start_listening
134	 *   .stop()                  — disconnect
135	 *   .deviceCommand(...)      — proxy
136	 *   .readAttribute(...)      — proxy
137	 *   .writeAttribute(...)     — proxy
138	 *   .commissionWithCode(...) — proxy
139	 *   .nodes                   — getter for client.nodes
140	 *   .serverInfo              — getter for client.serverInfo
141	 *   .on('attribute_changed', listener)
142	 *   .on('node_event'|'node_added'|'node_removed'|'node_updated', listener)
143	 *   .on('connected'|'disconnected'|'server_info', listener)
144	 *   .on('error', listener)
145	 *
146	 * The facade is itself an EventEmitter.
147	 */
148	async function createBridge(url) {
149	    if (typeof url !== 'string' || !url) throw new Error('createBridge: url required');
150	
151	    const mod = await loadMatterClientModule();
152	    const MatterClient = mod.MatterClient;
153	    if (typeof MatterClient !== 'function') {
154	        throw new Error('Could not load MatterClient from @matter-server/ws-client');
155	    }
156	    const WebSocketCtor = await loadWebSocketCtor();
157	
158	    const bridge = new EventEmitter();
159	    bridge.url = url;
160	    bridge._started = false;
161	    bridge._stopped = false;
162	
163	    // WS factory taps the message listener for per-attribute deltas
164	    const wsFactory = (wsUrl) => {
165	        const rawWs = new WebSocketCtor(wsUrl);
166	        return tapWebSocket(rawWs, bridge);
167	    };
168	
169	    const client = new MatterClient(url, wsFactory);
170	    bridge._client = client;
171	
172	    // Forward upstream events
173	    if (typeof client.addEventListener === 'function') {
174	        client.addEventListener('nodes_changed', () => bridge.emit('nodes_changed'));
175	        client.addEventListener('server_info_updated', () => bridge.emit('server_info', client.serverInfo));
176	        client.addEventListener('connection_lost', () => bridge.emit('disconnected'));
177	        if (mod.MatterClient && client.addEventListener.length >= 2) {
178	            // Some versions also expose server_shutdown
179	            try { client.addEventListener('server_shutdown', () => bridge.emit('disconnected')); } catch (_) {}
180	        }
181	    }
182	
183	    bridge.start = async function () {
184	        if (bridge._started) return;
185	        bridge._started = true;
186	        try {
187	            await client.startListening();
