1	'use strict';
2	
3	const crypto = require('crypto');
4	const { computeShape, extractIdentity } = require('../lib/shape');
5	const { buildInventory } = require('../lib/inventory');
6	const { attributeToMsg, aliveToMsg } = require('../lib/normalize');
7	
8	const VALID_FORMATS = new Set(['hal2', 'summary', 'node', 'inventory', 'resync']);
9	
10	function genId(prefix) {
11	    return `${prefix}_${crypto.randomBytes(5).toString('hex')}`;
12	}
13	
14	function buildThingTypeNode(template, baseLibIdMap) {
15	    // baseLibIdMap: Map<fnName, generatedId> — shared across items so refs resolve.
16	
17	    function resolveLibId(library, name) {
18	        const existing = baseLibIdMap.get(name);
19	        if (existing) return existing;
20	        const id = genId('lib');
21	        baseLibIdMap.set(name, id);
22	        const fn = library.find(f => f.name === name);
23	        return fn ? id : null;
24	    }
25	
26	    const ingressLib = (template.functions && template.functions.ingress) || [];
27	    const egressLib = (template.functions && template.functions.egress) || [];
28	
29	    // Build local library arrays
30	    const ingressList = ingressLib.map(f => {
31	        const id = baseLibIdMap.get(f.name) || genId('lib');
32	        baseLibIdMap.set(f.name, id);
33	        return { id, name: f.name, fn: f.fn };
34	    });
35	    const egressList = egressLib.map(f => {
36	        const id = baseLibIdMap.get(f.name) || genId('lib');
37	        baseLibIdMap.set(f.name, id);
38	        return { id, name: f.name, fn: f.fn };
39	    });
40	
41	    // Build items
42	    const items = (template.items || []).map(it => {
43	        const ep = it.endpoint;
44	        const cluster = it.cluster;
45	        const attr = it.attr;
46	        const filterValue = it.filterValue || `/${cluster}/${attr}`;
47	        const matchType = it.filterMatchType || 'StrEnd';
48	        const ingressId = it.ingress ? resolveLibId(ingressLib, it.ingress) : null;
49	        const egressId = it.egress ? resolveLibId(egressLib, it.egress) : null;
50	        const obj = {
51	            name: it.name,
52	            id: it.id,
53	            topicFilters: Array.isArray(it.topicFilters)
54	                ? it.topicFilters
55	                : [{ field: 'topic', matchType, value: filterValue }],
56	            topicFilterMode: it.topicFilterMode || (Array.isArray(it.topicFilters) && it.topicFilters.length > 1 ? 'or' : 'and'),
57	            topicSuffix: it.egress ? `./${ep}/${cluster}/${attr}` : '',
58	            type: it.readOnly ? 'status' : 'both',
59	            haType: it.haType || '',
60	            ingress: ingressId,
61	            egress: egressId,
62	            notes: it.notes || `Endpoint ${ep}, cluster ${cluster} attribute ${attr}`,
63	            output: '1',
64	            history: it.history === undefined ? true : !!it.history,
65	            historyAllUpdates: false,
66	        };
67	        if (it.readOnly) obj.readOnly = true;
68	        return obj;
69	    });
70	
71	    // Always add Alive item bound to the controller's synthetic /_alive/0 topic
72	    const aliveIngressId = resolveLibId(ingressLib, 'Pass-through');
73	    items.push({
74	        name: 'Alive',
75	        id: '1',
76	        topicFilters: [{ field: 'topic', matchType: 'StrEnd', value: '/_alive/0' }],
77	        topicFilterMode: 'and',
78	        topicSuffix: '',
79	        readOnly: true,
80	        type: 'status',
81	        ingress: aliveIngressId,
82	        egress: '',
83	    });
84	    // Make sure Pass-through ends up in the local library if it wasn't already
85	    if (aliveIngressId && !ingressList.find(f => f.id === aliveIngressId)) {
86	        ingressList.push({ id: aliveIngressId, name: 'Pass-through', fn: 'return msg.payload;' });
87	    }
88	
89	    return {
90	        id: template.id,
91	        type: 'hal2ThingType',
92	        name: template.name,
93	        contextStore: 'filesystem',
94	        nodestatus: template.nodestatus || '',
95	        nodestatusType: 'str',
96	        statusFn: "return '';",
97	        items,
98	        attributes: [],
99	        ingress: ingressList,
100	        egress: egressList,
101	        thingStatus: true,
102	        thingCommand: true,
103	        thingOutput: true,
104	        hbCheck: true,
105	        hbType: 'lwt',
106	        hbTTL: '',
107	        hbLWT: aliveIngressId,
108	        hbFilters: [{ field: 'topic', matchType: 'StrEnd', value: '/_alive/0' }],
109	        hbFilterMode: 'and',
110	        hbFilterVal: '',
111	        hbFilterType: '',
112	        hbPropVal: 'payload',
113	        hbPropType: 'msg',
114	        filterFunction: '0',
115	        outputs: '1',
116	    };
117	}
118	
119	function buildThingNode(matterNode, template, eventHandlerId, shape) {
120	    const nodeId = matterNode.node_id;
121	    const ident = extractIdentity(matterNode);
122	    const name = [ident.vendorName, ident.productName].filter(Boolean).join(' ').trim() || `Matter ${nodeId}`;
123	    return {
124	        id: `matter_thing_${nodeId}`,
125	        type: 'hal2Thing',
126	        eventHandler: eventHandlerId || '',
127	        thingType: template.id,
128	        name,
129	        attributes: [],
130	        topicFilters: [{ field: 'topic', matchType: 'mqtt', value: `matter/${nodeId}/#` }],
131	        topicFilter: '',
132	        topicFilterType: '',
133	        topicPrefix: `matter/${nodeId}`,
134	        notes: `Auto-genererad ${new Date().toISOString()}. shape=${shape}.`,
135	        outputs: 1,
136	        wires: [[]],
137	    };
138	}
139	
140	function resolveEventHandlerId(RED, explicitId) {
141	    if (explicitId) return explicitId;
142	    let found = '';
143	    try {
144	        RED.nodes.eachNode(function (n) {
145	            if (!found && n && n.type === 'hal2EventHandler') found = n.id;
146	        });
147	    } catch (_) { /* eachNode unavailable — fall through */ }
148	    return found;
149	}
150	
151	/**
152	 * Resolve a filter expression to a Matter nodeId string, or null for "match all".
153	 *  - undefined/null/empty → null (no filter)
154	 *  - numeric string ("48") → returned as-is
155	 *  - "last" (case-insensitive) → nodeId with max date_commissioned in bridge cache
156	 *  - anything else → null + warn
157	 */
158	function resolveFilter(node, bridge, raw) {
159	    if (raw === undefined || raw === null || raw === '') return null;
160	    const s = String(raw).trim();
161	    if (s === '') return null;
162	    if (/^\d+$/.test(s)) return s;
163	    if (s.toLowerCase() === 'last') {
164	        const nodes = bridge && bridge.nodes;
165	        if (!nodes) return null;
166	        let bestId = null;
167	        let bestTs = -Infinity;
168	        for (const key of Object.keys(nodes)) {
169	            const data = (nodes[key] && nodes[key].data) || nodes[key];
170	            if (!data || typeof data.node_id !== 'number') continue;
171	            const ts = data.date_commissioned ? Date.parse(data.date_commissioned) : NaN;
172	            if (Number.isFinite(ts) && ts > bestTs) {
173	                bestTs = ts;
174	                bestId = String(data.node_id);
175	            }
176	        }
177	        if (bestId == null) {
178	            node.warn('discover: no commissioned nodes for "last"');
179	            return null;
180	        }
181	        return bestId;
182	    }
183	    node.warn('discover: unrecognized filter value: ' + JSON.stringify(raw));
184	    return null;
185	}
186	
187	/**
188	 * Resolve filter from (msg.nodeId | numeric msg.payload | string msg.payload "last"/"42" | config.filter).
189	 * Returns { value: string|null, source: 'msg.nodeId'|'msg.payload'|'config'|'none' }.
190	 */
191	function pickFilterRaw(node, msg) {
192	    if (msg.nodeId !== undefined && msg.nodeId !== null && msg.nodeId !== '') {
193	        return { raw: msg.nodeId, source: 'msg.nodeId' };
194	    }
195	    if (typeof msg.payload === 'number' && Number.isFinite(msg.payload)) {
196	        return { raw: msg.payload, source: 'msg.payload' };
197	    }
198	    if (typeof msg.payload === 'string') {
199	        const s = msg.payload.trim();
200	        if (/^\d+$/.test(s) || s.toLowerCase() === 'last') {
201	            return { raw: s, source: 'msg.payload' };
202	        }
203	    }
204	    if (node.filter) return { raw: node.filter, source: 'config' };
205	    return { raw: null, source: 'none' };
206	}
207	
208	module.exports = function (RED) {
209	    function matterjsDiscover(config) {
210	        RED.nodes.createNode(this, config);
211	        const node = this;
212	        node.controller = RED.nodes.getNode(config.controller);
213	        node.format = config.format || 'hal2';
214	        node.eventHandlerId = String(config.eventHandlerId || '').trim();
215	        node.filter = String(config.filter || '').trim();
216	
217	        if (!node.controller) {
218	            node.status({ fill: 'red', shape: 'ring', text: 'no controller' });
219	            return;
220	        }
221	
222	        node.on('input', async function (msg, send, done) {
223	            const bridge = node.controller.getBridge();
224	            if (!bridge || !bridge.nodes) {
225	                node.status({ fill: 'yellow', shape: 'ring', text: 'no nodes cache' });
226	                done && done(new Error('matter bridge not ready or empty'));
227	                return;
228	            }
229	
230	            // msg-based config overrides (everything except name/controller)
231	            let effectiveFormat = node.format;
232	            if (typeof msg.format === 'string' && VALID_FORMATS.has(msg.format)) {
233	                effectiveFormat = msg.format;
234	            } else if (msg.format !== undefined) {
235	                node.warn('discover: ignoring invalid msg.format ' + JSON.stringify(msg.format));
236	            }
237	
238	            // Inventory: flat list of every node (vendor/model/part/fw + IPv6). Reuses the shared
239	            // builder; set msg.readNetwork to read 0/51/0 on demand for nodes missing it in cache.
240	            if (effectiveFormat === 'inventory') {
241	                try {
242	                    const inventory = await buildInventory(node.controller, { readMissingNetwork: !!msg.readNetwork });
243	                    msg.payload = inventory;
244	                    node.status({ fill: 'green', shape: 'dot', text: `inventory — ${inventory.length} nodes` });
245	                    send(msg);
246	                    done && done();
247	                } catch (e) {
248	                    node.status({ fill: 'red', shape: 'ring', text: 'inventory failed' });
249	                    done && done(e);
250	                }
251	                return;
252	            }
253	
254	            let effectiveEhConfig = node.eventHandlerId;
255	            if (typeof msg.eventHandlerId === 'string' && msg.eventHandlerId !== '') {
256	                effectiveEhConfig = msg.eventHandlerId.trim();
257	            }
258	
259	            // Filter (msg.nodeId > msg.payload numeric/"last" > config.filter), supports "last"
260	            const picked = pickFilterRaw(node, msg);
261	            const effectiveFilter = resolveFilter(node, bridge, picked.raw);
262	
263	            // Resync: replay the current node cache as hal2-format messages (alive + attribute
264	            // values), re-seeding downstream Things. Mirrors the old "inject get_nodes" trick.
265	            // Honours the node-id filter above; wire this node's output into your Things' stream.
266	            if (effectiveFormat === 'resync') {
267	                const replay = [];
268	                for (const key of Object.keys(bridge.nodes)) {
269	                    const data = bridge.nodes[key] && (bridge.nodes[key].data || bridge.nodes[key]);
270	                    if (!data || typeof data.node_id !== 'number') continue;
271	                    const nodeId = data.node_id;
272	                    if (effectiveFilter && String(nodeId) !== effectiveFilter) continue;
273	                    const attrs = data.attributes || {};
274	                    const available = !!data.available;
275	                    const eps = new Set();
276	                    for (const k of Object.keys(attrs)) {
277	                        const m = k.match(/^(\d+)\/29\/0$/);
278	                        if (m && Number(m[1]) !== 0) eps.add(Number(m[1]));
279	                    }
280	                    for (const ep of eps) replay.push(aliveToMsg(nodeId, ep, available));
281	                    // Real attribute values — skip global attrs/clusters (>= 0xFFF8: AttributeList etc).
282	                    for (const k of Object.keys(attrs)) {
283	                        const m = k.match(/^(\d+)\/(\d+)\/(\d+)$/);
284	                        if (!m) continue;
285	                        const cluster = Number(m[2]), attribute = Number(m[3]);
286	                        if (cluster >= 0xFFF8 || attribute >= 0xFFF8) continue;
287	                        replay.push(attributeToMsg({ nodeId, endpoint: Number(m[1]), cluster, attribute, value: attrs[k] }));
288	                    }
289	                }
290	                node.status({
291	                    fill: 'blue', shape: 'dot',
292	                    text: `resync (${effectiveFilter || 'all'}) — ${replay.length} msgs`,
293	                });
294	                send([null, replay]);   // resync events on output 2 (keep them off the result output)
295	                done && done();
296	                return;
297	            }
298	
299	            const ehId = resolveEventHandlerId(RED, effectiveEhConfig);
300	
301	            const nodes = bridge.nodes;
302	            const templates = node.controller.getTemplates();
303	            const shapeIndex = node.controller.getShapeIndex();
304	
305	            const ttIds = new Set();
306	            const output = [];
