1	'use strict';
2	
3	// Builds a flat, human-/machine-friendly inventory of every commissioned Matter node from the
4	// controller's live node cache. Shared by the matterjsDiscover "inventory" format, the
5	// controller's admin endpoint + sidebar, and the metadata emission into hal2.
6	
7	const { computeShape, extractIdentity, extractNetwork } = require('./shape');
8	
9	/**
10	 * @param {object} controller  the matterjsController config node (getBridge, getShapeIndex)
11	 * @param {object} [opts]
12	 * @param {boolean} [opts.readMissingNetwork]  if a node has no cached 0/51/0, read it on demand
13	 * @returns {Promise<Array>} per-node inventory entries, sorted by node_id
14	 */
15	async function buildInventory(controller, opts = {}) {
16	    const readMissingNetwork = !!opts.readMissingNetwork;
17	    const bridge = controller && controller.getBridge && controller.getBridge();
18	    if (!bridge || !bridge.nodes) return [];
19	    const shapeIndex = (controller.getShapeIndex && controller.getShapeIndex()) || new Map();
20	    const nodes = bridge.nodes;
21	
22	    const out = [];
23	    for (const key of Object.keys(nodes)) {
24	        const mn = nodes[key];
25	        if (!mn) continue;
26	        // Upstream MatterNode wraps `data` and exposes attributes getter — normalise both shapes.
27	        const data = mn.data || mn;
28	        const flat = {
