node -e "
const assert = require('assert');
const { EventEmitter } = require('events');
const inMod = require('./core/in.js');

let ctor;
const RED = {
    nodes: {
        createNode(node, config) {
            Object.assign(node, new EventEmitter());
            Object.setPrototypeOf(node, EventEmitter.prototype);
            node.status = () => {};
            node.sent = [];
            node.send = (m) => node.sent.push(m);
        },
        getNode() { return controllerMock; },
        registerType(name, fn) { ctor = fn; },
    },
};

const wrappedNode = {
    data: {
        node_id: 48, available: true,
        attributes: { '1/29/0': [{'0': 266}], '2/29/0': [{'0': 266}], '0/29/0': [{'0': 22}] },
    },
};
const controllerMock = new EventEmitter();
controllerMock.getBridge = () => ({ nodes: { '48': wrappedNode } });

inMod(RED);
const node = {};
ctor.call(node, { controller: 'c1', format: 'hal2' });

// node_removed med numeriskt data (som matter-server skickar)
controllerMock.emit('matter:node_removed', 48);
const aliveMsgs = node.sent.filter(m => m.topic && m.topic.includes('_alive'));
assert.strictEqual(aliveMsgs.length, 2, 'one _alive per endpoint (1,2)');
assert(aliveMsgs.every(m => m.payload === false), 'all offline');
assert(aliveMsgs.some(m => m.topic === 'matter/48/1/_alive/0'));
assert(aliveMsgs.some(m => m.topic === 'matter/48/2/_alive/0'));

// node borta ur cachen -> fallback endpoint 1
node.sent.length = 0;
controllerMock.getBridge = () => ({ nodes: {} });
controllerMock.emit('matter:node_removed', { node_id: 99 });
assert.strictEqual(node.sent.length, 1);
assert.strictEqual(node.sent[0].topic, 'matter/99/1/_alive/0');

// raw-format: inga _alive
const rawNode = {};
ctor.call(rawNode, { controller: 'c1', format: 'raw' });
controllerMock.emit('matter:node_removed', 48);
assert.strictEqual(rawNode.sent.filter(m => m.topic && m.topic.includes('_alive')).length, 0);

// close avregistrerar
node.emit('close');
assert.strictEqual(controllerMock.listenerCount('matter:node_removed'), 1, 'only rawNode left');
console.log('in.js node_removed OK');
"
